//! The files that are generated by their name alone: lock files, minified files, source maps and snapshots

use serde::Serialize;

/// File names of package manager lock files
const LOCK_FILES: [&str; 22] = [
  "Cargo.lock",
  "Gemfile.lock",
  "Package.resolved",
  "Pipfile.lock",
  "Podfile.lock",
  "bun.lock",
  "bun.lockb",
  "composer.lock",
  "deno.lock",
  "flake.lock",
  "go.sum",
  "go.work.sum",
  "gradle.lockfile",
  "mix.lock",
  "npm-shrinkwrap.json",
  "package-lock.json",
  "packages.lock.json",
  "pdm.lock",
  "pnpm-lock.yaml",
  "poetry.lock",
  "uv.lock",
  "yarn.lock",
];

/// What the name of a generated file says it is
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
#[cfg_attr(feature = "specta", derive(specta::Type))]
#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
#[serde(rename_all = "camelCase")]
pub enum GeneratedName {
  /// A lock file of a package manager (`Cargo.lock`, `pnpm-lock.yaml`, `go.sum`, …)
  LockFile,
  /// `*.min.js`, `*.min.css`
  Minified,
  /// `*.map`
  SourceMap,
  /// `*.snap`: the expected output of a snapshot test, written by its tool
  Snapshot,
}

/// What the name of `path` says it is, when it is the name of a generated file
pub fn generated_name(path: &str) -> Option<GeneratedName> {
  let name = file_name(path);
  let (stem, extension) = name.rsplit_once('.').unwrap_or((name, ""));
  let extension_is = |known: &str| extension.eq_ignore_ascii_case(known);
  let minified = stem.rsplit_once('.').is_some_and(|(_, last)| last.eq_ignore_ascii_case("min"));
  if LOCK_FILES.contains(&name) {
    Some(GeneratedName::LockFile)
  } else if minified && (extension_is("js") || extension_is("css")) {
    Some(GeneratedName::Minified)
  } else if extension_is("map") {
    Some(GeneratedName::SourceMap)
  } else if extension_is("snap") {
    Some(GeneratedName::Snapshot)
  } else {
    None
  }
}

/// A lock file of a package manager: the only names that `bd commits` and `bd status` leave out
pub fn is_lock_file(path: &str) -> bool {
  generated_name(path) == Some(GeneratedName::LockFile)
}

pub(crate) fn file_name(path: &str) -> &str {
  path.rsplit('/').next().unwrap_or(path)
}
